+// An IN-list is a genuine parser role (RowExpr::constructor == false),
+// not a projected record or an opaque string. Reuse each catalog's existing
+// field/qualifier/function validator for the original member expressions.
+// Values are still evaluated by the ordinary typed ExprEvaluator below.
+template<class Visit>
+static void validateCatalogMembershipValue(const dbms::Expr* value, const Visit& visit) {
+    const auto* row = dynamic_cast<const dbms::RowExpr*>(value);
+    if (row && row->constructor) {
+        for (const auto& field : row->elements)
+            validateCatalogMembershipValue(field.get(), visit);
+        return;
+    }
+    visit(value);
+}
+
+template<class Visit>
+static bool validateCatalogMembershipOperands(const dbms::BinaryOpExpr* binary,
+                                               const Visit& visit) {
+    // These are operator grammar tags, never function-name identity tests.
+    if (binary->op != "IN" && binary->op != "NOT IN" &&
+        binary->op != "in" && binary->op != "not in") return false;
+    const auto* list = dynamic_cast<const dbms::RowExpr*>(binary->right.get());
+    if (!list || list->constructor) return false;
+    validateCatalogMembershipValue(binary->left.get(), visit);
+    for (const auto& member : list->elements)
+        validateCatalogMembershipValue(member.get(), visit);
+    return true;
+}
