struct Mutation {DmlResult result;std::string state,diagnostic;bool good=false,actualHandled=false,actualErrorReturn=false,typeCaptureRestored=false,sessionRestored=false;};
Mutation mutate(const std::string& sql,Session& session,bool capture=true) {
