        for(uint64_t i=0;i<h.generatedBound;++i) {
            Frame frame;frame.offset=extent-reader.remaining();
            frame.source=reader.scalar<uint64_t>();frame.column=reader.scalar<uint64_t>();frame.id=reader.scalar<uint64_t>();
