bool StorageEngine::analyzeTable(const std::string& dbname,
                                 const std::string& tablename) {
    if (!tableExists(dbname, tablename)) return false;
    TableSchema tbl = getTableSchema(dbname, tablename);

    TableStats stats;
    stats.rowCount = 0;
    std::map<std::string, std::vector<std::string>> allVals;
    std::map<std::string, size_t> nullCounts;
    bool capturePhysicalNulls = tbl.formatVersion == DATA_FILE_FORMAT_VERSION;
    for (size_t column = 0; column < tbl.len; ++column)
        if (tbl.cols[column].generatedKind == 'v') capturePhysicalNulls = false;

    if (!forEachRow(dbname, tablename, [&](uint32_t pageId, uint16_t slotId, const char* data, size_t len) {
        stats.rowCount++;
        std::string row(data, len);
        std::vector<bool> capturedNulls;
        std::optional<BufferedNullRowBinding> capturedBinding;
        bool bitmapAttempted = false;
        for (size_t i = 0; i < tbl.len; ++i) {
            const std::string& cname = tbl.cols[i].dataName;
            if (g_scanHeapTuple && dbms::isNull(g_scanHeapTuple, static_cast<int>(i))) {
                ++nullCounts[cname];
                continue;
            }
            // Start exactly at the first original non-NULL nullable-cell
            // extraction. All-NULL/NOT-NULL-only rows keep zero probes.
            if (capturePhysicalNulls && !bitmapAttempted &&
                tbl.cols[i].isNull && g_scanHeapTuple) {
                bitmapAttempted = true;
                // Retain a real current-file check per used row. Borrow only
                // the same tuple that this scan still pins; never reuse a
                // bitmap from a different allocator/page generation.
                PageAllocator* current = getPageAllocator(dbname, tablename);
                if (current) {
                    char* buffer = current->fetchPage(pageId);
                    if (buffer) {
                        struct Pin {
                            PageAllocator* allocator;
                            uint32_t page;
                            ~Pin() { allocator->unpinPage(page); }
                        } pin{current, pageId};
                        PageWrapper page(buffer, current->pageSize(), tbl.formatVersion);
                        const char* tuple = nullptr;
                        size_t length = 0;
                        if (page.read(slotId, tuple, length) &&
                            length >= sizeof(HeapTupleHeaderData) &&
                            tuple == reinterpret_cast<const char*>(g_scanHeapTuple)) {
                            capturedNulls.assign(tbl.len, false);
                            for (size_t column = 0; column < tbl.len; ++column)
                                capturedNulls[column] = dbms::isNull(
                                    castHeapHeader(tuple), static_cast<int>(column));
                            capturedBinding.emplace(tbl, capturedNulls);
                        }
                    }
                }
                // If a coherent capture is unavailable, execute the complete
                // original per-cell extraction below. Exceptions propagate.
            }
            std::string val = extractColumnValue(row, tbl, i);
            allVals[tbl.cols[i].dataName].push_back(val);
        }
    })) return false;

    const size_t HIST_BUCKETS = 10;
    const size_t MCV_TOP_N = 10;
    for (size_t i = 0; i < tbl.len; ++i) {
        const std::string& cname = tbl.cols[i].dataName;
        StorageEngine::ColumnStats cs;
        cs.nullCount = nullCounts[cname];
        auto& vals = allVals[cname];
        const Column& column = tbl.cols[i];
        AnalyzeComparisonCache comparison;
        if (vals.size() > 1) {
            std::vector<size_t> order;
            std::vector<bool> comparable;
            order.reserve(vals.size());
            comparable.reserve(vals.size());
            for (size_t valueIndex = 0; valueIndex < vals.size(); ++valueIndex) {
                // Validate once per input, reusing only an immediately
                // preceding byte-identical value in this same column/run.
                const auto& value = vals[valueIndex];
                comparable.push_back(valueIndex > 0 && vals[valueIndex - 1] == value
                    ? comparable.back()
                    : compareValues(column, value, false, value, false, "=") != PredicateTruth::Unknown);
                order.push_back(valueIndex);
            }
            // Original validation above is complete before any cache setup.
            // An unsupported/failed cache retains the entire old comparator.
            comparison.prepare(column, vals, comparable);
            std::sort(order.begin(), order.end(),
                [&column, &vals, &comparable, &comparison](size_t left, size_t right) -> bool {
                    // Retain the orderable/non-orderable partition: a
                    // per-pair fallback would break strict weak ordering.
                    if (comparable[left] != comparable[right]) return comparable[left];
                    if (!comparable[left]) return vals[left] < vals[right];
                    // Comparability (and locale validity) was checked first.
                    if (vals[left] == vals[right]) return false;
                    if (const auto compared = comparison.compare(
                            left, right, vals[left], vals[right])) return *compared < 0;
                    return compareValues(column, vals[left], false, vals[right], false, "<")
                        == PredicateTruth::True;
                });
            // Apply the destination-to-source permutation in place. Scalar
            // cache keys follow exactly the same cycles as the raw strings;
            // no extra raw datum or array of raw string objects is copied.
            for (size_t start = 0; start < order.size(); ++start) {
                if (order[start] == start) continue;
                std::string saved = std::move(vals[start]);
                const auto savedKey = comparison.take(start);
                size_t destination = start;
                while (order[destination] != start) {
                    const size_t source = order[destination];
                    vals[destination] = std::move(vals[source]);
                    comparison.move(destination, source);
                    order[destination] = destination;
                    destination = source;
                }
                vals[destination] = std::move(saved);
                comparison.put(destination, savedKey);
                order[destination] = destination;
            }
        }
        if (!vals.empty()) {
            cs.minVal = vals.front();
            cs.maxVal = vals.back();
        }
        // Build equi-depth histogram
        if (vals.size() >= HIST_BUCKETS * 2) {
            const size_t perBucket = vals.size() / HIST_BUCKETS;
            for (size_t b = 0; b < HIST_BUCKETS; ++b) {
                const size_t start = b * perBucket;
                const size_t end = (b == HIST_BUCKETS - 1) ? vals.size() - 1 : (b + 1) * perBucket;
                // Keep the original decoded value, including exact numeric
                // precision and floating-point fractions; never stoll/round it.
                cs.histogram.push_back({vals[start], vals[end]});
            }
        }
        // Compute MCV
        cs.mcv = computeCachedTypedMCV(
            column, vals, comparison, cs.cardinality, MCV_TOP_N);
        stats.colStats[cname] = cs;
    }

    // Load existing stats, update this table's entry (preserve multi-col stats)
    std::map<std::string, TableStats> allStats;
    auto spath = statsPath(dbname);
    if (std::filesystem::exists(spath)) {
        std::ifstream ifs(spath);
        std::string line;
        while (std::getline(ifs, line)) {
            if (line.empty()) continue;
            std::stringstream ss(line);
            std::string tname, cname;
            ss >> tname >> cname;
            if (cname == "__rows__") {
                std::string rc;
                std::getline(ss, rc);
                try { allStats[tname].rowCount = std::stoull(rc); } catch (...) {}
                continue;
            }
            if (cname == "__multi__") {
                std::string colKey;
                ss >> colKey;
                std::string rest;
                std::getline(ss, rest);
                // Reconstruct line for parseStatsLine
                allStats[tname].multiColStats[colKey] = parseStatsLine(tname + " " + colKey + " " + rest);
                continue;
            }
            allStats[tname].colStats[cname] = parseStatsLine(line);
        }
    }
    // Preserve multi-col stats from existing entry
    auto it = allStats.find(tablename);
    if (it != allStats.end()) {
        stats.multiColStats = it->second.multiColStats;
    }
    allStats[tablename] = stats;

    // Write back
    std::ostringstream serialized;
    for (const auto& kv : allStats) {
        serialized << kv.first << " __rows__ " << kv.second.rowCount << "||\n";
        for (const auto& cv : kv.second.colStats) {
            writeStatsEntry(serialized, kv.first, cv.first, cv.second);
        }
        for (const auto& mv : kv.second.multiColStats) {
            serialized << kv.first << " __multi__ " << mv.first << " " << mv.second.cardinality
                << "|" << mv.second.minVal << "|" << mv.second.maxVal << "|";
            for (size_t i = 0; i < mv.second.histogram.size(); ++i) {
                if (i > 0) serialized << ";";
                serialized << mv.second.histogram[i].first << "," << mv.second.histogram[i].second;
            }
            serialized << "|" << mcvToString(mv.second.mcv) << "\n";
        }
    }
    return index_file::writeAtomically(spath, serialized.str());
}

static bool indexExpressionMayReadVirtual(const std::string& source,const TableSchema& table) {
    if(source.empty())return false;
    ExprPtr root;
    try {root=GeneratedColumnProgram::parseDefinition(source);}catch(const DbError&){return true;}
    bool reads=false;
    std::function<void(const Expr*)> visit=[&](const Expr* node) {
        if(!node || reads)return;
        if(node->preparedSubquery){reads=true;return;}
        if(const auto* column=dynamic_cast<const ColumnRefExpr*>(node)) {
            if(column->column=="*"){reads=true;return;}
            bool found=false;
            for(size_t i=0;i<table.len;++i)if(table.cols[i].dataName==column->column) {
                found=true;reads=reads||table.cols[i].generatedKind=='v';
            }
            if(!found)reads=true; // Preserve original handling of unknown roles.
            return;
        }
        if(const auto* value=dynamic_cast<const BinaryOpExpr*>(node)){visit(value->left.get());if(value->op!="::"&&value->op!="COLLATE")visit(value->right.get());}
        else if(const auto* value=dynamic_cast<const UnaryOpExpr*>(node))visit(value->operand.get());
        else if(const auto* value=dynamic_cast<const CastExpr*>(node))visit(value->operand.get());
        else if(const auto* value=dynamic_cast<const CaseExpr*>(node)){visit(value->switchExpr.get());for(const auto& arm:value->whenClauses){visit(arm.first.get());visit(arm.second.get());}visit(value->elseExpr.get());}
        else if(const auto* value=dynamic_cast<const FunctionCallExpr*>(node)) {
            for(size_t i=0;i<value->args.size();++i) {
                if(i==0 && value->schema.empty() && SQLParser::toLower(value->funcName)=="extract")
                    if(const auto* label=dynamic_cast<const ColumnRefExpr*>(value->args[i].get());label&&label->schema.empty()&&label->table.empty())continue;
                visit(value->args[i].get());
            }
            for(const auto& arg:value->namedArgs)visit(arg.value.get());visit(value->filter.get());
        } else if(const auto* value=dynamic_cast<const ArrayExpr*>(node))for(const auto& item:value->elements)visit(item.get());
        else if(const auto* value=dynamic_cast<const RowExpr*>(node))for(const auto& item:value->elements)visit(item.get());
        else if(const auto* value=dynamic_cast<const QuantifiedComparisonExpr*>(node)){visit(value->left.get());visit(value->right.get());}
    };
    visit(root.get());return reads;
}
static bool indexColumnIsVirtual(const std::string& name,const TableSchema& table) {
    for(size_t i=0;i<table.len;++i)if(table.cols[i].dataName==name)return table.cols[i].generatedKind=='v';
    return true; // unknown metadata retains the exact full-map fallback
}
static bool secondaryMayReadVirtual(const StorageEngine::IndexMetadata& metadata,const TableSchema& table) {
    if(metadata.isExpression?indexExpressionMayReadVirtual(metadata.name,table):indexColumnIsVirtual(metadata.name,table))return true;
    return indexExpressionMayReadVirtual(metadata.whereCondition,table);
}
static bool compositeMayReadVirtual(const StorageEngine::CompositeIndexInfo& metadata,const TableSchema& table) {
    if(metadata.columns.empty())return true;
    for(const auto& name:metadata.columns)if(indexColumnIsVirtual(name,table))return true;
    return indexExpressionMayReadVirtual(metadata.whereCondition,table);
}

static std::map<std::string, std::string> indexRowValuesFromBuffer(
    StorageEngine& engine,
    const TableSchema& table,
    const std::string& rowBuffer,
    const std::string& dbname,bool omitVirtual=false) {
    std::map<std::string, std::string> values;
    for (size_t i = 0; i < table.len; ++i) {
        if(omitVirtual && table.cols[i].generatedKind=='v')continue;
        values[table.cols[i].dataName] = engine.extractColumnValue(
            rowBuffer, table, i, dbname, true);
    }
    return values;
}

static bool secondaryIndexEntryFromBuffer(
    StorageEngine& engine,
    const StorageEngine::IndexMetadata& metadata,
    const TableSchema& table,
    const std::string& rowBuffer,
    const std::string& dbname,
    EvaluatedIndexEntry& entry) {
    const auto values = indexRowValuesFromBuffer(
        engine,table,rowBuffer,dbname,!secondaryMayReadVirtual(metadata,table));
    return secondaryIndexEntry(
        metadata, table, values, dbname, entry, &engine);
}

static bool compositeIndexEntryFromBuffer(
    StorageEngine& engine,
    const StorageEngine::CompositeIndexInfo& metadata,
    const TableSchema& table,
    const std::string& rowBuffer,
    const std::string& dbname,
    EvaluatedIndexEntry& entry) {
    const auto values = indexRowValuesFromBuffer(
        engine,table,rowBuffer,dbname,!compositeMayReadVirtual(metadata,table));
    return compositeIndexEntry(
        metadata, table, values, dbname, entry, &engine);
}

std::set<size_t> physicalNullColumns;
for (size_t i = 0; i < tbl.len; ++i) {
    if (storedValues.find(tbl.cols[i].dataName) == storedValues.end() ||
        actualNullColumns.count(tbl.cols[i].dataName) != 0) {
        physicalNullColumns.insert(i);
    }
}

const bool legacyFullImage=shouldEnforceRLS(tbl,StorageEngine::getRLSUser()) ||
    !filterTriggers(operationTriggers,tablename,"before","insert").empty() ||
    !filterTriggers(operationTriggers,tablename,"after","insert").empty();
for (size_t i = 0; i < tbl.len; ++i) {
    const auto& column = tbl.cols[i];
    if(deferVirtualInputs && column.generatedKind=='v' && !legacyFullImage)continue;
    if (actualValues.emplace(column.dataName, std::string{}).second)
        actualNullColumns.insert(column.dataName);
}

