def cpp_mask(s):
    """Mask C++ comments/literals, preserving byte positions and line endings."""
    out = list(s)
    i = 0
    while i < len(s):
        end = None
        if s.startswith('//', i):
            end = s.find('\n', i + 2)
            if end < 0: end = len(s)
        elif s.startswith('/*', i):
