def cpp_mask(s):
    """Mask C++ comments/literals, preserving byte positions and line endings."""
    if s in _MASK_CACHE: return _MASK_CACHE[s]
    out = list(s)
    i = 0
    while i < len(s):
        end = None
        if s.startswith('//', i):
            end = s.find('\n', i + 2)
