        ++checked;observed={};observed.baseline=liveBytes();bool good=false;
        try{good=action();}catch(const std::exception& error){std::cerr<<"TYPED_SORT_OPERATOR_EXCEPTION "<<label<<" : "<<error.what()<<'\n';}
